1	package cli
2	
3	import (
4		"context"
5		"fmt"
6		"strings"
7	
8		"github.com/entireio/entire-brain/internal/apiurl"
9	
10		"github.com/spf13/cobra"
11	)
12	
13	// whereamiResult is the host CLI's `entire repo whereami --json` contract
14	// (COR-2029): the repo's region-local ULID and its cell API base URL.
15	type whereamiResult struct {
16		RepoID string `json:"repo_id"`
17		APIURL string `json:"api_url"`
18	}
19	
20	type connectOptions struct {
21		repoID string
22		apiURL string
23	}
24	
25	func newConnectCommand(opts Options) *cobra.Command {
26		var connectOpts connectOptions
27		cmd := &cobra.Command{
28			Use:   "connect",
29			Short: "Bind this repository to its hosted brain explicitly",
30			Long: `connect binds this repository to its hosted brain: it records the repo id and
31	API base URL (non-secrets only — the host CLI's own login mints a fresh token
32	per sync), then runs one immediate sync so the first pull happens right away.
33	
34	Running connect is OPTIONAL: the daemon and session-end hook resolve the
35	binding automatically through the host CLI (entire repo whereami) and fall
36	back to local-only until that succeeds. Use connect to bind explicitly —
37	a non-default cell, a staging target, or before the host CLI supports
38	whereami. Pass --repo-id and --api-url to bypass resolution entirely.`,
39			Args: cobra.NoArgs,
40			RunE: func(cmd *cobra.Command, args []string) error {
41				return runConnect(cmd, opts, connectOpts)
42			},
43		}
44		cmd.Flags().StringVar(&connectOpts.repoID, "repo-id", "", "Hosted repo id (region-local ULID)")
45		cmd.Flags().StringVar(&connectOpts.apiURL, "api-url", "", "Entire API base URL, https://")
46		return cmd
47	}
48	
49	func runConnect(cmd *cobra.Command, opts Options, connectOpts connectOptions) error {
50		ctx := cmd.Context()
51		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil))
52		if err != nil {
53			return err
54		}
55		if !local {
56			return fmt.Errorf("connect requires a local repository path")
57		}
58		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
59		if err != nil {
60			return err
61		}
62	
63		repoID := strings.TrimSpace(connectOpts.repoID)
64		apiURL := strings.TrimSpace(connectOpts.apiURL)
65		if repoID == "" || apiURL == "" {
66			resolved, whereamiErr := resolveWhereami(ctx, opts.Runner, repoDir)
67			if whereamiErr != nil {
68				// An already-connected repo stays re-connectable without flags:
69				// re-connect means re-sync (the blind-spot note's remedy), not
70				// re-resolve.
71				if existing, present, readErr := readHostedRepoBinding(storage.BrainDir); readErr == nil && present {
72					resolved = whereamiResult{RepoID: existing.RepoID, APIURL: existing.BaseURL}
73				} else {
74					return fmt.Errorf("connect: resolve hosted placement (`entire repo whereami --json`): %w; pass --repo-id and --api-url explicitly", whereamiErr)
75				}
76			}
77			if repoID == "" {
78				repoID = resolved.RepoID
79			}
80			if apiURL == "" {
81				apiURL = resolved.APIURL
82			}
83		}
84		binding, err := bindHostedRepo(storage.BrainDir, repoID, apiURL)
85		if err != nil {
86			return fmt.Errorf("connect: %w", err)
87		}
88		fmt.Fprintf(cmd.OutOrStdout(), "connected: repo %s via %s\n", binding.RepoID, binding.BaseURL)
89		// Connect doubles as the initial pull so a fresh clone receives team
90		// memories immediately; failures note and never fail the connect.
91		return hostedFactsSyncAndPull(ctx, cmd.ErrOrStderr(), opts, repoDir, storage, hostedSyncBranch(ctx, opts.Runner, repoDir))
92	}
93	
94	// bindHostedRepo validates and normalizes the target, then writes the
95	// repo-level binding. Cell URLs are commonly quoted with their /api/v1 prefix
96	// (whereami's api_url, docs examples), but the factsync client appends
97	// /api/v1/repos/... itself — storing the suffix would 404 every sync.
98	func bindHostedRepo(brainDir, repoID, apiURL string) (hostedRepoBinding, error) {
99		if strings.TrimSpace(repoID) == "" {
100			return hostedRepoBinding{}, fmt.Errorf("hosted repo id is empty")
101		}
102		validated, err := apiurl.Validate(apiURL)
103		if err != nil {
104			return hostedRepoBinding{}, err
105		}
106		binding := hostedRepoBinding{RepoID: strings.TrimSpace(repoID), BaseURL: strings.TrimSuffix(validated, "/api/v1")}
107		if err := writeHostedRepoBinding(brainDir, binding); err != nil {
108			return hostedRepoBinding{}, err
109		}
110		return binding, nil
111	}
112	
113	// resolveWhereami shells out to the host CLI for this repo's hosted placement.
114	func resolveWhereami(ctx context.Context, runner CommandRunner, repoDir string) (whereamiResult, error) {
115		ctx, cancel := context.WithTimeout(ctx, hostedShellOutTimeout)
116		defer cancel()
117		stdout, _, err := runner.Run(ctx, repoDir, hostEntireBinary, "repo", "whereami", "--json")
118		if err != nil {
119			return whereamiResult{}, err
120		}
121		var result whereamiResult
122		if err := decodeHostCLIJSON(stdout, &result); err != nil {
123			return whereamiResult{}, fmt.Errorf("parse whereami json: %w", err)
124		}
125		return result, nil
126	}
