237	// unsyncedHostedFactsBlindSpot notes a branch that has not synced against the
238	// CONNECTED hosted brain: repo-level hosted.json present, per-branch
239	// hosted-target.json absent or recording a different target (a marker left by
240	// a previous connection must not suppress the note). Purely local reads; no
241	// network.
242	func unsyncedHostedFactsBlindSpot(brainDir, branch string) string {
243		// The branchless surface (emptyResultBlindSpot) passes ""; facts sync per
244		// branch, so there is no empty-branch marker and the note would be
245		// nonsense — and would hide the coverage notes below it.
246		if strings.TrimSpace(branch) == "" {
247			return ""
248		}
249		binding, connected, err := readHostedRepoBinding(brainDir)
250		if err != nil || !connected {
251			return ""
252		}
253		if checkHostedFactsBinding(brainDir, branch, binding.RepoID, binding.BaseURL) == nil {
254			return ""
255		}
256		// The remedy must be a command that PULLS: `facts sync` only publishes
257		// (and would write the marker that silences this note without fetching
258		// anything); connect runs the full sync-and-pull.
259		return fmt.Sprintf("note: this repository is connected to a hosted brain but branch %q has not synced with it; run 'entire brain connect' or wait for the next daemon tick", branch)
260	}
